/*=============================================================================
 * boot_anim - the startup animation: the zeta function spiralling up its own
 * critical line.
 *
 * This header is the MATHS and the CHOREOGRAPHY - the projection, the
 * smoothing, the colour and the timeline. boot_anim.c is the drawing and the
 * five seconds of frame loop, and boot_anim_curve.h is the curve itself,
 * generated by tools/gen_zeta_curve.py. The split is the one gfx_color.h,
 * icons.h and ui_style.h already make: everything here is integer arithmetic
 * with no BSP, no driver and no framebuffer in sight, so
 * test/suites/suite_boot_anim.c can check all of it on a laptop. Nobody can
 * eyeball a fixed-point projection and tell you whether it is the right one.
 *
 * WHAT IS BEING DRAWN
 *
 * Three axes. Two of them are the complex plane that zeta's VALUE lives in -
 * the real part running down and to the right, the imaginary part down and to
 * the left at 45 degrees - and they are drawn as a floor, with a grid on it.
 * The third is t, straight up, which is the HEIGHT UP THE CRITICAL LINE the
 * function is being evaluated at.
 *
 * The curve is then zeta(1/2 + it) for t from 0 to 35, plotted at height t.
 * It winds round the vertical axis because the value keeps circling the
 * origin, and the loops grow as t does. Where it actually touches the t axis
 * the value is zero - and those five points are the first five nontrivial
 * zeros of the zeta function, marked as the pen passes them.
 *
 * So the picture is not decorative arithmetic: the Riemann hypothesis is the
 * conjecture that this line is the only place those crossings happen.
 *
 * THE CAMERA ORBITS
 *
 * It does not stay at that first side-on view. Over the course of the climb
 * the camera pitches up, as though gliding across the surface of a sphere
 * centred on the origin while turning to keep it in view: the floor tips from
 * "a plane receding into the distance" toward "a disc facing the viewer", the
 * t axis foreshortens from its full vertical length toward a point, and what
 * was a helix seen from the side ends up read almost face-on, as the spiral
 * it always was. Almost, not exactly - stopping short of a true top-down view
 * is what keeps the floor legibly tilted rather than flattened to a line with
 * no depth in it.
 *
 * The origin's own position on screen drifts to match, from low on the panel
 * up to the mirror image of where it started - see boot_anim_view() for the
 * exact relationship. Two effects, one motion: rotating the world about a
 * fixed point does not move that point, so the drift is a second, explicit
 * animation riding alongside the orbit, not a side effect of it.
 *
 * FIXED POINT, AND FOUR SCALES OF IT
 *
 * The chip has no FPU, so everything is integers. Mixing the scales up is the
 * mistake to watch for:
 *
 *   Q12   a value of zeta. 4096 is 1.0, one unit of the floor grid.
 *   Q8    a height t. 256 is 1.0, and 35 * 256 still fits an int16.
 *   Q8    the projection's own axis vectors, in pixels per unit.
 *   Q15   sines and cosines of the camera's tilt. 32767 is 1.0.
 *===========================================================================*/
#pragma once

#include <stdint.h>

#include "boot/boot_anim_curve.h"

#define BOOT_ANIM_Q    12
#define BOOT_ANIM_ONE  (1 << BOOT_ANIM_Q)   /* 4096 == 1.0 */
#define BOOT_ANIM_TQ   8                    /* t's own fixed point */

/* The origin - where t is 0 and zeta is 0. (w/2, h*3/4) is where the camera
 * starts: low and centred, because everything else is above it. It does not
 * stay there - see boot_anim_view() below - but this is that starting point,
 * and the fixed point everything else orbits around. Defined ahead of both
 * "The camera" and "The projection" below because each needs it. */
static inline int boot_anim_origin_x(int w) { return w / 2; }
static inline int boot_anim_origin_y(int h) { return (h * 3) / 4; }

/*---------------------------------------------------------------------------
 * The camera
 *
 * Everything the orbit needs, ahead of "The projection" below because
 * boot_anim_screen_y() consumes a boot_anim_view_t and so needs the type and
 * the sine table it is built from to already exist.
 *-------------------------------------------------------------------------*/

/* A quarter wave at 65 points - sin(k * pi/128), Q15 - reflected into the
 * other three quadrants by boot_anim_sin() below. The 65th entry exists so
 * interpolation always has a point to its right; it is sin(pi/2), the one
 * sample the quarter wave shares with the next.
 *
 * Generated as round(32767 * sin(k * pi / 128)). Nothing here checks that
 * against libm - test/run_tests.sh links no maths library - so
 * suite_boot_anim.c checks the properties instead: the wave rises, it ends at
 * 1, and sin^2 + cos^2 is 1 everywhere. A mistyped entry fails several of
 * those at once. */
static const int16_t boot_anim_sin_quarter[65] = {
         0,    804,   1608,   2410,   3212,   4011,   4808,   5602,
      6393,   7179,   7962,   8739,   9512,  10278,  11039,  11793,
     12539,  13279,  14010,  14732,  15446,  16151,  16846,  17530,
     18204,  18868,  19519,  20159,  20787,  21403,  22005,  22594,
     23170,  23731,  24279,  24811,  25329,  25832,  26319,  26790,
     27245,  27683,  28105,  28510,  28898,  29268,  29621,  29956,
     30273,  30571,  30852,  31113,  31356,  31580,  31785,  31971,
     32137,  32285,  32412,  32521,  32609,  32678,  32728,  32757,
     32767,
};

/* sin over the first quarter turn: `r` is 0..16384, the answer is Q15.
 *
 * Interpolated between table points rather than snapped to the nearer one.
 * The table is coarse - 256 steps to the turn, 1.4 degrees - and a caller
 * summing many of these (the projection sums one per point drawn) would see
 * the snapping error compound rather than average out. */
static inline int32_t boot_anim_sin_quadrant(uint32_t r)
{
    const uint32_t i = r >> 8;
    if (i >= 64) {
        return boot_anim_sin_quarter[64];
    }
    const int32_t a = boot_anim_sin_quarter[i];
    const int32_t b = boot_anim_sin_quarter[i + 1];
    return a + (((b - a) * (int32_t)(r & 0xFF)) >> 8);
}

/* sin of a 16-bit phase (65536 == one turn), Q15. */
static inline int32_t boot_anim_sin(uint16_t phase)
{
    const uint32_t quadrant = (uint32_t)phase >> 14;
    const uint32_t rest     = (uint32_t)phase & 0x3FFF;

    switch (quadrant) {
    case 0:  return  boot_anim_sin_quadrant(rest);
    case 1:  return  boot_anim_sin_quadrant(16384u - rest);
    case 2:  return -boot_anim_sin_quadrant(rest);
    default: return -boot_anim_sin_quadrant(16384u - rest);
    }
}

static inline int32_t boot_anim_cos(uint16_t phase)
{
    return boot_anim_sin((uint16_t)(phase + 16384u));
}

/* How far the camera tilts by the end of the climb, as a 16-bit phase
 * (65536 == 360 degrees). 58 degrees, not 90: the whole point of stopping
 * short is a floor that is still visibly a floor, not a line with no depth
 * left in it - see "THE CAMERA ORBITS" at the top of this file. */
#define BOOT_ANIM_PHI_END_PHASE 10559   /* round(58 / 360 * 65536) */

/* THE ROTATION, TURNED INTO NINE CONSTANTS AT COMPILE TIME
 *
 * The camera has two screen-space directions, right and down, each a
 * 3-vector of how far one unit of (Re, Im, t) moves a point in that screen
 * direction. `right` is the pitch axis - the orbit rotates the world about
 * it, so it never moves, and BOOT_ANIM_RE_X/IM_X below are exactly what they
 * always were. `down` is what rotates.
 *
 * Given a fixed unit vector `axis` (= normalised `right`) and `A` (= `down`
 * at zero tilt, today's original constants read back as directions rather
 * than pixels), Rodrigues' rotation of `A` about `axis` through angle phi is
 *
 *     down(phi) = A*cos(phi) + (axis x A)*sin(phi) + axis*(axis . A)*(1 - cos(phi))
 *
 * Both `axis` and `A` are fixed, so everything about that formula that is
 * NOT cos(phi) or sin(phi) is a compile-time constant. Multiplying out and
 * collecting terms:
 *
 *     down(phi) = D*cos(phi) + B*sin(phi) + C
 *
 *     where  C = axis * (axis . A)
 *            D = A - C
 *            B = axis x A
 *
 * which is what turns a rotation - cross products, dot products, a matrix -
 * into three vectors baked in at compile time and two multiplies at runtime.
 * D, B and C below are those three vectors, each split into a Re/Im/t triple
 * and each already scaled the way BOOT_ANIM_RE_X was: Re and Im components
 * carry BOOT_ANIM_Z_PX, the t component carries BOOT_ANIM_T_PX, all as Q8.
 * boot_anim_view() below recombines them with cos(phi)/sin(phi) each frame.
 *
 * Verified two ways before being trusted here: the algebraic identity above
 * checked against a from-scratch rotation at seven angles from 0 to 90
 * degrees (agreement to float noise), and the resulting fixed-point path
 * checked against that same float reference across the whole 0..3000ms
 * timeline and the whole curve (worst case under 3px, and the drawn part of
 * the curve never left the panel at any point in the sweep). */
#define BOOT_ANIM_D_RE_Y  4152
#define BOOT_ANIM_D_IM_Y  5517
#define BOOT_ANIM_D_T_Y  (-2304)
#define BOOT_ANIM_B_RE_Y  5387
#define BOOT_ANIM_B_IM_Y  7159
#define BOOT_ANIM_B_T_Y   1776
#define BOOT_ANIM_C_RE_Y (-1087)
#define BOOT_ANIM_C_IM_Y   818
#define BOOT_ANIM_C_T_Y     0

/* Everything boot_anim_screen_x()/screen_y() need for one frame, computed
 * once rather than once per point: the rotated screen-space weights for
 * Re/Im/t, all Q8 like BOOT_ANIM_RE_X was, and the frame's origin - which,
 * unlike everything before the finale (see "The finale" below), can now
 * drift horizontally as well as vertically.
 *
 * The CONSTRUCTOR, boot_anim_view(), is defined further down, after both
 * the choreography and the finale sections - it needs boot_anim_pen() and
 * boot_anim_finale_reach(), and this struct only needs to be a complete
 * TYPE this early, not have its constructor defined yet, for
 * boot_anim_screen_x()/screen_y() below to compile against it. */
typedef struct {
    int32_t re_y, im_y, t_y;   /* Q8 - see boot_anim_screen_y() */
    int     ox, oy;             /* pixels */
} boot_anim_view_t;

/*---------------------------------------------------------------------------
 * The projection
 *
 * Axonometric, not perspective - three directions on screen and no divide per
 * point - but the directions are not all fixed any more. The real axis's
 * screen direction never changes; the imaginary and t axes' do, orbiting
 * together as the camera pitches. See "THE CAMERA ORBITS" above for what that
 * looks like and boot_anim_view() above for where the numbers come from.
 *
 * Screen size arrives as a parameter rather than as GFX_WIDTH/GFX_HEIGHT,
 * because gfx.h drags in the BSP and this file has to compile on a host.
 * gfx_dirty.h has the same problem and mirrors the two numbers as literals;
 * taking them as arguments leaves nothing to drift out of step.
 *-------------------------------------------------------------------------*/

#define BOOT_ANIM_Z_PX  35     /* pixels per unit of zeta's value */
#define BOOT_ANIM_T_PX   9     /* pixels per unit of t            */
#define BOOT_ANIM_T_MAX 35     /* the top of the climb            */

/* The floor grid has no edge: its lines run until they leave the panel, and
 * what bounds it is a fade rather than a boundary.
 *
 * A grid drawn to a fixed square reads as a square tile floating in the dark,
 * which is a thing sitting in the scene. A grid that thins out with distance
 * reads as a plane carrying on past the screen, which is what a coordinate
 * plane actually is. gfx_line() clips, so rings that fall off the edge cost
 * nothing to ask for.
 *
 * RINGS is therefore how far the fade reaches rather than how big the floor
 * is: ring FADE is fully dark, so nothing past it is worth drawing at all. */
#define BOOT_ANIM_GRID_RINGS 7
#define BOOT_ANIM_GRID_FADE  7

/* Where one unit along each axis lands, in Q8 pixels.
 *
 *   real       20 degrees below horizontal, to the right
 *   imaginary  45 degrees below horizontal, to the left
 *
 * 45 for the imaginary axis because that is the angle that reads as "going
 * away from you". 20 rather than another 45 for the real one because two
 * symmetric axes make a floor that looks like it is being seen edge on, with
 * the grid squares collapsed into slivers.
 *
 * Q8 rather than Q12 for headroom: these multiply a Q12 value of up to about
 * 3.7, and at Q12 that product would come within a factor of two of
 * overflowing an int32. That failure would show up as the curve folding in
 * half at its widest point - not as anything that announces itself.
 */
#define BOOT_ANIM_RE_X  8420   /*  cos(20) * Z_PX * 256           */
#define BOOT_ANIM_IM_X (-6336) /* -cos(45) * Z_PX * 256           */

/* value -> screen x, for the CURRENT frame's view.
 *
 * The WEIGHTS (BOOT_ANIM_RE_X/IM_X) are unaffected by the camera orbiting,
 * because the real axis's screen direction is the pitch axis - see
 * boot_anim_view() - and rotating about an axis leaves that axis exactly
 * where it was. The ORIGIN is a different matter: view->ox can drift during
 * the finale (see "The finale" below), which is why this takes a view at
 * all now, where once it did not.
 *
 * The shift is 20 because a Q12 value times a Q8 pixels-per-unit is Q20.
 *
 * NOT util/fixed.h, deliberately. fx_mul_floor() exists to make the widening
 * cast unforgettable at sites that need one; this does not need one, because
 * the operands were sized so the product cannot overflow an int32 - the
 * largest is about 1.7e8 against a 2.1e9 ceiling. Routing it through a 64-bit
 * helper would put back the arithmetic the scale choice exists to avoid, on a
 * path that runs several thousand times a frame.
 *
 * The two terms are also summed BEFORE the shift, which fx_mul_floor() cannot
 * express: flooring each product separately and then adding can land a pixel
 * off the one the geometry asks for. */
static inline int boot_anim_screen_x(int32_t re_q12, int32_t im_q12,
                                     const boot_anim_view_t *view)
{
    return view->ox +
           (int)((re_q12 * BOOT_ANIM_RE_X + im_q12 * BOOT_ANIM_IM_X) >> 20);
}

/* (value, height) -> screen y, for the CURRENT frame's view - see
 * boot_anim_view() above for what a view is and where its numbers come from.
 *
 * Same 32-bit reasoning as boot_anim_screen_x(): view->re_y and view->im_y
 * are Q8 by construction (see boot_anim_view()), so this is the same shift-
 * by-20, sum-before-shift arithmetic, just reading the frame's rotated
 * weights instead of a fixed compile-time pair.
 *
 * view->t_y carries an extra Q8 of fraction on top of that - it has to,
 * since unlike the old bare BOOT_ANIM_T_PX it is not always exactly nine, it
 * is nine SCALED BY A ROTATING DIRECTION, so it needs to represent values
 * between whatever t foreshortens to and back - hence the wider shift, 8
 * more than the re/im term needs to shed the same Q8. */
static inline int boot_anim_screen_y(int h, int32_t re_q12, int32_t im_q12,
                                     int32_t t_q8,
                                     const boot_anim_view_t *view)
{
    (void)h;    /* baked into view->oy already - see boot_anim_view() */
    return view->oy +
           (int)((re_q12 * view->re_y + im_q12 * view->im_y) >> 20) +
           (int)((t_q8 * view->t_y) >> (BOOT_ANIM_TQ + 8));
}

/*---------------------------------------------------------------------------
 * Smoothing
 *
 * 205 samples of a curve that crosses most of the screen is a chord every six
 * pixels or so, and at that size a polyline reads as a polyline - the tight
 * turns near the axis visibly have corners. Rather than carry more samples,
 * the ones there are get drawn as a spline.
 *-------------------------------------------------------------------------*/

/* Straight segments per span. Four puts a joint every pixel and a half at the
 * curve's tightest, which is well under what anyone can see. */
#define BOOT_ANIM_SPLINE_STEPS 4

typedef struct {
    int32_t re, im;   /* Q12 */
    int32_t t;        /* Q8  */
} boot_anim_pt_t;

/* A point on the uniform quadratic B-spline through c0, c1, c2, at `t_q12`
 * from 0 - which lands on the midpoint of c0 and c1 - to BOOT_ANIM_ONE, the
 * midpoint of c1 and c2. Consecutive spans therefore meet, and the result is
 * one continuous curve.
 *
 * WHY A B-SPLINE AND NOT A CATMULL-ROM
 *
 * The obvious choice for "smooth curve through my points" interpolates them,
 * and Catmull-Rom overshoots wherever they turn sharply. Here that is exactly
 * the interesting part of the picture - the curve whipping round the axis at
 * a zero - and an overshoot would put a bulge precisely where the whole point
 * is that the curve passes through a particular place.
 *
 * A B-spline stays inside the convex hull of its control points instead,
 * because its weights are non-negative and sum to a constant. It does not
 * pass through them - it cuts the corners - and that IS the smoothing: the
 * samples are a sampling of a smooth function, so the corners are an artifact
 * of the sampling rather than a feature of the curve.
 *
 * Quadratic rather than cubic for one practical reason: a quadratic's weights
 * sum to 2, so normalising is a shift. A cubic's sum to 6, and a divide per
 * coordinate per sub-step is thousands of divides a frame on the slowest
 * integer instruction this chip has.
 */
static inline boot_anim_pt_t boot_anim_spline(boot_anim_pt_t c0,
                                              boot_anim_pt_t c1,
                                              boot_anim_pt_t c2,
                                              int32_t t_q12)
{
    /* 32-bit throughout, for the same reason boot_anim_screen_x() is - see
     * its comment on why util/fixed.h is not used here. t_q12 is at most
     * BOOT_ANIM_ONE, so the weights are at most 2.0 in Q12 and the three
     * weighted samples sum to well under 4e7. */
    const int32_t u  = BOOT_ANIM_ONE - t_q12;
    const int32_t w0 = (u * u) >> BOOT_ANIM_Q;
    const int32_t w2 = (t_q12 * t_q12) >> BOOT_ANIM_Q;

    /* The three weights sum to 2.0 by construction, so the middle one is
     * never computed from its own polynomial - and so cannot drift from the
     * other two if it is not. */
    const int32_t w1 = 2 * BOOT_ANIM_ONE - w0 - w2;

    boot_anim_pt_t p;
    p.re = (w0 * c0.re + w1 * c1.re + w2 * c2.re) >> (BOOT_ANIM_Q + 1);
    p.im = (w0 * c0.im + w1 * c1.im + w2 * c2.im) >> (BOOT_ANIM_Q + 1);
    p.t  = (w0 * c0.t  + w1 * c1.t  + w2 * c2.t ) >> (BOOT_ANIM_Q + 1);
    return p;
}

/* Sample `i` of the generated curve, clamped at both ends.
 *
 * Clamping rather than wrapping or refusing is what pins the spline to the
 * ends of the curve: a repeated first control point makes the first span
 * start exactly at the first sample instead of half a span along it. */
static inline boot_anim_pt_t boot_anim_sample(int i)
{
    if (i < 0) {
        i = 0;
    } else if (i >= BOOT_ANIM_CURVE_POINTS) {
        i = BOOT_ANIM_CURVE_POINTS - 1;
    }
    boot_anim_pt_t p;
    p.re = boot_anim_curve[i].re;
    p.im = boot_anim_curve[i].im;
    p.t  = boot_anim_curve[i].t;
    return p;
}

/*---------------------------------------------------------------------------
 * The choreography
 *
 * Every phase is a function of milliseconds since power-up rather than of a
 * frame counter, so the animation lasts five seconds whatever the frame rate
 * turns out to be - and it does move, because a frame costs a full-screen
 * transfer plus however much curve there is to draw by then.
 *-------------------------------------------------------------------------*/

#define BOOT_ANIM_MS 5000

#define BOOT_ANIM_AXES_MS        450   /* the axes grow out of the origin */

#define BOOT_ANIM_GRID_START_MS  150
#define BOOT_ANIM_GRID_RING_MS    45   /* each ring waits for the one inside */
#define BOOT_ANIM_GRID_FADE_MS   300

#define BOOT_ANIM_PEN_START_MS   520
#define BOOT_ANIM_PEN_MS        1980   /* the curve is done at 2500 */

/* The title arrives after the curve, not during it - see "The title" below -
 * with 200ms of held breath between the two. */
#define BOOT_ANIM_TITLE_START_MS 2700

#define BOOT_ANIM_FADE_START_MS 4600   /* dissolve into the launcher */

/* 0 before `start_ms`, 255 from `start_ms + dur_ms` on, linear between. */
static inline uint8_t boot_anim_ramp(uint32_t now_ms, uint32_t start_ms,
                                     uint32_t dur_ms)
{
    if (now_ms <= start_ms) {
        return 0;
    }
    const uint32_t elapsed = now_ms - start_ms;
    if (dur_ms == 0 || elapsed >= dur_ms) {
        return 255;
    }
    return (uint8_t)((elapsed * 255u) / dur_ms);
}

/* Fast off the mark, settling as it arrives. Motion that starts and stops at
 * the same speed reads as mechanical; one squared term is enough to stop it
 * looking like a progress bar. */
static inline uint8_t boot_anim_ease_out(uint8_t linear)
{
    const uint32_t left = 255u - linear;
    return (uint8_t)(255u - (left * left) / 255u);
}

/* How far along each axis the pen has reached, 0..255 of the way to its far
 * end. A FRACTION, not a pixel count: the three arms are three different
 * lengths on screen and still have to arrive together. */
static inline uint8_t boot_anim_axis_reach(uint32_t now_ms)
{
    return boot_anim_ease_out(boot_anim_ramp(now_ms, 0, BOOT_ANIM_AXES_MS));
}

/* Floor grid lines fade in from the origin outward - `ring` is 1 for the
 * first line either side of an axis, 2 for the next, and so on - and fade
 * OUT again with distance, which is what gives the floor no edge.
 *
 * The two fades multiply. The first is the animation arriving; the second is
 * the plane receding, and it is what the eye reads as depth on a projection
 * that has no perspective in it at all. */
/* The brightest the floor is ever allowed to get.
 *
 * Low, and the number that mattered most here. The floor is backdrop: it says
 * where the plane is and then gets out of the way. Drawn at anything like
 * full strength it competes with the curve for attention and wins, because
 * there is a great deal more of it - which is exactly what the first version
 * of this did, and the curve disappeared into a plaid tablecloth. */
#define BOOT_ANIM_GRID_MAX 56

static inline uint8_t boot_anim_grid_alpha(uint32_t now_ms, int ring)
{
    if (ring >= BOOT_ANIM_GRID_FADE) {
        return 0;
    }
    const uint32_t start = BOOT_ANIM_GRID_START_MS +
                           (uint32_t)ring * BOOT_ANIM_GRID_RING_MS;
    const uint32_t arrived = boot_anim_ramp(now_ms, start,
                                            BOOT_ANIM_GRID_FADE_MS);

    /* Squared, not linear: a linear falloff still has visible lines most of
     * the way out and then stops, which puts an edge back on the floor in a
     * different place. Squared, the outer rings are already almost gone by
     * the time they run out. */
    const uint32_t left = (uint32_t)(BOOT_ANIM_GRID_FADE - ring);
    const uint32_t near = left * left * BOOT_ANIM_GRID_MAX /
                          ((uint32_t)BOOT_ANIM_GRID_FADE * BOOT_ANIM_GRID_FADE);

    return (uint8_t)((arrived * near) / 255u);
}

_Static_assert(BOOT_ANIM_PEN_START_MS + BOOT_ANIM_PEN_MS <=
               BOOT_ANIM_FADE_START_MS,
               "the curve must be finished before the picture starts fading");

/*---------------------------------------------------------------------------
 * The title
 *
 * "Autana", in ordinary horizontal type - wide and short, the way any word
 * reads. Positioned and laid out in the VIEWER'S frame, not the panel's own:
 * this board is held turned a quarter from its native upright (see
 * display.h's DISPLAY_LANDSCAPE and its own measured-not-derived comment),
 * so "wide and short" and "left to right" mean wide, short and
 * left-to-right to someone holding the board that way, not to the raw
 * framebuffer. BOOT_ANIM_TITLE_VIEW_W/H below are that viewer's frame -
 * GFX_HEIGHT x GFX_WIDTH, the panel's own dimensions turned a quarter - and
 * every position in this section is a coordinate in it. boot_anim.c's
 * draw_title() is the one place that turns a point in this frame into the
 * panel coordinate + glyph rotation gfx_text_font() actually wants; nothing
 * above it needs to know the panel is mounted portrait.
 *
 * Everything else in this file - the floor, the axes, the curve, the
 * finale's turn and shift - stays in the panel's own raw coordinates,
 * untouched by this: only the word has a reading direction that makes the
 * mismatch visible, so only the word needed fixing.
 *
 * Each letter flies in from the left on its own clock, staggered so they
 * arrive one after another rather than as one block. What makes it more than
 * a slide is the vertical wobble riding along that flight: a sine wave whose
 * frequency winds down and whose amplitude shrinks together, so the letter
 * does not merely slide to a stop - it visibly settles, the way a struck
 * bell's ring narrows before it goes quiet, arriving exactly flat and
 * exactly on target at the same instant.
 *-------------------------------------------------------------------------*/

#define BOOT_ANIM_TITLE     "Autana"
#define BOOT_ANIM_TITLE_LEN 6

#define BOOT_ANIM_TITLE_SCALE 3    /* glyph scale - see gfx_text_font()   */
#define BOOT_ANIM_TITLE_GAP   3    /* extra px of tracking between glyphs */

/* The viewer's frame this whole section lays out in - see this section's
 * own top comment. GFX_HEIGHT x GFX_WIDTH (448 x 368) turned a quarter, not
 * GFX_WIDTH x GFX_HEIGHT: boot_anim.h stays BSP-free (no GFX_ include), so
 * these are spelled out as their own numbers rather than pulled from gfx.h,
 * the same choice suite_ui_transform.c's own top comment makes for the same
 * reason. */
#define BOOT_ANIM_TITLE_VIEW_W 448
#define BOOT_ANIM_TITLE_VIEW_H 368

/* Where the word rests, in the viewer's frame - approximately a third of
 * the way across and a little over a quarter down, measured against a real
 * render rather than derived from anything else on screen. */
#define BOOT_ANIM_TITLE_VIEW_X 170
#define BOOT_ANIM_TITLE_VIEW_Y 100

#define BOOT_ANIM_TITLE_STAGGER_MS  140   /* each letter starts this much
                                            * after the one before it       */
#define BOOT_ANIM_TITLE_FLIGHT_MS   900   /* how long ONE letter's flight is */
#define BOOT_ANIM_TITLE_ENTRY_PX    260   /* how far off-panel it starts    */

/* The wobble: how many oscillations are packed into the early part of the
 * flight (as a raw phase value - see boot_anim_sin()'s own 65536-per-turn
 * convention, so this is 3.5 turns) and the peak swing right at the start. */
#define BOOT_ANIM_TITLE_TURNS_PHASE 229376   /* round(3.5 * 65536) */
#define BOOT_ANIM_TITLE_AMPLITUDE_PX  22

/* The vertical wobble, `d_q12` being how much of its OWN flight a letter has
 * left - BOOT_ANIM_ONE at the moment it sets off, 0 the instant it arrives.
 *
 * THE CHIRP
 *
 * phase is proportional to d^2, not to d. Equal steps of d near d=0 then
 * produce ever-smaller steps of phase, which is what makes the oscillation
 * visibly slow down as the letter approaches rather than just shrink at a
 * constant rate - a chirp, not a vibration fading out. Checked directly in
 * suite_boot_anim.c: the gaps between successive zero crossings of this
 * function, walking d from 1 to 0, must strictly grow.
 *
 * THE LANDING
 *
 * Amplitude is proportional to d as well (not d^2 - a gentler taper reads
 * as settling, where d^2 would cut the swing off too abruptly near the
 * end). Because amplitude reaches exactly zero at d=0 regardless of what
 * phase happens to be at that instant, the letter always lands dead flat on
 * its target - the wobble does not need to be timed to land on a particular
 * phase, only to have decayed by then, which it always has. */
static inline int boot_anim_title_wobble(int32_t d_q12)
{
    if (d_q12 <= 0) {
        return 0;
    }
    /* d^2, Q12. d_q12 <= BOOT_ANIM_ONE, so this cannot overflow an int32 -
     * same 32-bit reasoning as boot_anim_spline()'s own squared terms. */
    const int32_t d2_q12 = (d_q12 * d_q12) >> BOOT_ANIM_Q;

    /* Q12 fraction of BOOT_ANIM_TITLE_TURNS_PHASE, truncated to 16 bits -
     * the truncation is not a bug to guard against, it is how a phase past
     * one full turn wraps back into boot_anim_sin()'s range. Comfortably
     * inside int32 range: the largest product is under 1e9 against a 2.1e9
     * ceiling, so - like boot_anim_screen_x()'s own arithmetic - this does
     * not reach for util/fixed.h's widening cast. */
    const uint16_t phase = (uint16_t)
        ((d2_q12 * BOOT_ANIM_TITLE_TURNS_PHASE) >> BOOT_ANIM_Q);

    const int32_t amp = (BOOT_ANIM_TITLE_AMPLITUDE_PX * d_q12) >> BOOT_ANIM_Q;
    return (int)((amp * boot_anim_sin(phase)) >> 15);
}

typedef struct {
    int x, y;   /* pixels */
} boot_anim_title_pos_t;

/* Where letter `i` of BOOT_ANIM_TITLE sits, in the viewer's frame (see this
 * section's own top comment), at `now_ms`. Letters are laid out left to
 * right in their FINAL row first - see final_x below - and each one's
 * flight is just a horizontal lerp toward its own final_x, with the wobble
 * added to a fixed baseline.
 *
 * The row starts at BOOT_ANIM_TITLE_VIEW_X/Y, a fixed target rather than one
 * read from a live view: the row a letter is flying TOWARD has to stay put
 * for the whole flight, not move while the letter is chasing it. */
static inline boot_anim_title_pos_t boot_anim_title_letter(int i,
                                                            uint32_t now_ms)
{
    const uint32_t start = BOOT_ANIM_TITLE_START_MS +
                           (uint32_t)i * BOOT_ANIM_TITLE_STAGGER_MS;
    const uint8_t u8 = boot_anim_ease_out(
        boot_anim_ramp(now_ms, start, BOOT_ANIM_TITLE_FLIGHT_MS));

    const int cell = 8 * BOOT_ANIM_TITLE_SCALE + BOOT_ANIM_TITLE_GAP;
    const int final_x = BOOT_ANIM_TITLE_VIEW_X + i * cell;
    const int start_x = final_x - BOOT_ANIM_TITLE_ENTRY_PX;

    boot_anim_title_pos_t p;
    p.x = start_x + (((final_x - start_x) * u8) / 255);

    const int32_t d_q12 = BOOT_ANIM_ONE -
                          (((int32_t)u8 * BOOT_ANIM_ONE) / 255);
    p.y = BOOT_ANIM_TITLE_VIEW_Y + boot_anim_title_wobble(d_q12);
    return p;
}

_Static_assert(BOOT_ANIM_TITLE_START_MS +
               (BOOT_ANIM_TITLE_LEN - 1) * BOOT_ANIM_TITLE_STAGGER_MS +
               BOOT_ANIM_TITLE_FLIGHT_MS <= BOOT_ANIM_FADE_START_MS,
               "every letter must have landed before the picture starts "
               "fading");

/*---------------------------------------------------------------------------
 * Colour
 *
 * The panel is an AMOLED: an unlit pixel is genuinely off, not a backlight
 * leaking through black, so saturated colour on a true black field is the one
 * thing this screen does that an LCD cannot. Hence a hue wheel rather than a
 * house colour - the curve turns most of the way round it on the way up, so
 * height reads as colour and the whole climb is one gradient.
 *
 * Only the HUE is computed here. Brightness and desaturation come out as
 * amounts to mix toward the background and toward white, and the mixing is
 * gfx_color_mix() in gfx_color.h - already written, already tested, and
 * already aware that the panel's green channel has a bit more range than the
 * other two.
 *-------------------------------------------------------------------------*/

/* A whole turn: six sectors of 256, so the sector is a shift and the ramp
 * within one is a byte. */
#define BOOT_ANIM_HUE_TURN 1536

/* 0xRRGGBB at full saturation and full brightness. */
static inline uint32_t boot_anim_hue_rgb(int hue)
{
    hue %= BOOT_ANIM_HUE_TURN;
    if (hue < 0) {
        hue += BOOT_ANIM_HUE_TURN;
    }

    const uint32_t ramp = (uint32_t)(hue & 0xFF);   /* rising edge, 0..255 */
    const uint32_t fall = 255u - ramp;

    switch (hue >> 8) {
    case 0:  return (0xFFu << 16) | (ramp << 8);            /* red     -> yellow  */
    case 1:  return (fall << 16) | (0xFFu << 8);            /* yellow  -> green   */
    case 2:  return (0xFFu << 8) | ramp;                    /* green   -> cyan    */
    case 3:  return (fall << 8) | 0xFFu;                    /* cyan    -> blue    */
    case 4:  return (ramp << 16) | 0xFFu;                   /* blue    -> magenta */
    default: return (0xFFu << 16) | fall;                   /* magenta -> red     */
    }
}

/* The grid's own colour, as a hue wheel position, drifting with time and
 * with distance from the origin.
 *
 * The floor is the one thing on screen that is up the whole time and does
 * nothing, so it is where a slow colour change costs nothing and is not in
 * competition with anything. Distance is folded in as well as time, so the
 * rings do not all change together - the colour travels outward as a wave
 * instead of the whole floor blinking. */
#define BOOT_ANIM_GRID_HUE_MS     2600   /* one whole turn takes this long */
#define BOOT_ANIM_GRID_HUE_SPREAD 70     /* wheel positions per ring outward */

static inline int boot_anim_grid_hue(uint32_t now_ms, int ring)
{
    const uint32_t turn = (now_ms % BOOT_ANIM_GRID_HUE_MS) *
                          BOOT_ANIM_HUE_TURN / BOOT_ANIM_GRID_HUE_MS;
    return (int)turn + ring * BOOT_ANIM_GRID_HUE_SPREAD;
}

/* How much of the curve has been drawn, as a Q12 fraction of its length.
 *
 * A fraction of LENGTH, not of t: the samples are spaced at a constant
 * distance ON SCREEN (see tools/gen_zeta_curve.py), so walking them at a
 * constant rate moves the pen at a constant speed. Pacing by t instead would
 * crawl round the wide loops and race up the straight stretches between
 * them. */
static inline int32_t boot_anim_pen(uint32_t now_ms)
{
    const uint8_t linear = boot_anim_ramp(now_ms, BOOT_ANIM_PEN_START_MS,
                                          BOOT_ANIM_PEN_MS);
    return ((int32_t)linear * BOOT_ANIM_ONE) / 255;
}

/* Everything drawn is mixed up from the background by this, so the last
 * stretch dissolves the whole picture rather than cutting from a lit screen
 * straight to the menu. */
static inline uint8_t boot_anim_ink(uint32_t now_ms)
{
    return (uint8_t)(255u - boot_anim_ramp(now_ms, BOOT_ANIM_FADE_START_MS,
                                           BOOT_ANIM_MS - BOOT_ANIM_FADE_START_MS));
}

#define BOOT_ANIM_HUE_START 875    /* azure, at the foot of the climb */
#define BOOT_ANIM_HUE_SWEEP 1200   /* most of a turn by the top       */

/* SEVERAL PENS, NOT ONE
 *
 * One pen puts one colour on the curve at a time, and this panel can show
 * rather more than that. Five of them run the same curve at a fixed spacing,
 * each carrying its own fifth of the wheel, so at any moment most of the
 * gamut is on screen at once and the curve reads as being washed by colour
 * rather than drawn in it.
 *
 * The leading pen is still the one that reveals the curve; the rest travel
 * over ground already covered. */
#define BOOT_ANIM_TRAILS    5

/* How far apart the pens run, as a Q12 fraction of the whole curve. */
#define BOOT_ANIM_TRAIL_GAP 768

/* How far behind a pen its own trail still glows. A quarter of the curve
 * each: long enough to fade out slowly rather than read as a spark being
 * dragged along, short enough that five of them stay five bands instead of
 * merging into one uniform glow.
 *
 * A power of two so the falloff below is a shift rather than a divide, of
 * which there would otherwise be tens of thousands a frame. */
#define BOOT_ANIM_TRAIL_SHIFT 10
#define BOOT_ANIM_TRAIL_Q12   (1 << BOOT_ANIM_TRAIL_SHIFT)

/* Strokes at least this lit are drawn this many pixels across instead of
 * one, so the live parts of the curve are visibly heavier than the settled
 * ones. */
#define BOOT_ANIM_FAT_TRAIL 150
#define BOOT_ANIM_FAT_WIDTH 3

/* Where pen `k` is, as a Q12 fraction of the curve. Negative until it has set
 * off, which is what staggers their starts without a second clock. */
static inline int32_t boot_anim_trail_pos(int32_t pen_q12, int k)
{
    return pen_q12 - (int32_t)k * BOOT_ANIM_TRAIL_GAP;
}

/* The wheel position pen `k` carries, spread evenly round it. */
static inline int boot_anim_trail_hue(int k)
{
    return k * (BOOT_ANIM_HUE_TURN / BOOT_ANIM_TRAILS);
}

typedef struct {
    int     hue;     /* wheel position; boot_anim_hue_rgb() wraps it */
    uint8_t bloom;   /* mix that far toward white                    */
    uint8_t glow;    /* mix that far up from the background          */
    uint8_t width;   /* pixels across                                */
} boot_anim_stroke_t;

/* How one piece of the curve is coloured: `along_q12` is where that piece
 * sits along the curve, `pen_q12` is where the LEADING pen has got to.
 *
 * Two things are added. A BASE, which depends only on position and is what
 * the finished picture looks like once the pens have stopped; and whichever
 * PEN is closest in front of this piece, which is what makes the drawing look
 * like drawing.
 *
 * The strongest pen wins outright rather than the five being summed. Summing
 * saturates wherever two trails overlap - and they overlap constantly - so
 * the bands smear into one bright stretch and their colours average out
 * toward white, which is the opposite of the point.
 *
 * Its hue is mixed in BY STRENGTH rather than switched to, so a piece of
 * curve halfway between two pens comes out halfway between their colours
 * instead of snapping from one to the other as the lead changes.
 *
 * Each trail falls off linearly rather than as a square. A squared falloff
 * piles the glow up right behind the head and is over almost at once, and a
 * trail that fades out slowly is the entire point of having one. */
static inline boot_anim_stroke_t boot_anim_stroke(int32_t along_q12,
                                                  int32_t pen_q12)
{
    boot_anim_stroke_t s;

    const int32_t base_glow  = 132 + ((along_q12 * 60) >> BOOT_ANIM_Q);
    const int32_t base_bloom = (along_q12 * 24) >> BOOT_ANIM_Q;
    const int base_hue = BOOT_ANIM_HUE_START +
                         (int)((along_q12 * BOOT_ANIM_HUE_SWEEP) >> BOOT_ANIM_Q);

    int32_t best = 0;
    int     best_hue = 0;

    for (int k = 0; k < BOOT_ANIM_TRAILS; k++) {
        const int32_t behind = boot_anim_trail_pos(pen_q12, k) - along_q12;
        if (behind < 0 || behind >= BOOT_ANIM_TRAIL_Q12) {
            continue;   /* this piece is ahead of that pen, or long past it */
        }
        const int32_t trail = 255 - ((behind * 255) >> BOOT_ANIM_TRAIL_SHIFT);
        if (trail > best) {
            best = trail;
            best_hue = boot_anim_trail_hue(k);
        }
    }

    /* (best + 1) >> 8, not best / 255: a shift is a divide's worth of cycles
     * cheaper and there are tens of thousands of these a frame, and the +1 is
     * what makes the shift land exactly on the endpoints - without it a
     * full-strength trail comes out one short of full brightness. */
    s.hue   = base_hue + ((best_hue * (best + 1)) >> 8);
    s.glow  = (uint8_t)(base_glow  + (((255 - base_glow) * (best + 1)) >> 8));
    s.bloom = (uint8_t)(base_bloom + (((90 - base_bloom) * (best + 1)) >> 8));
    s.width = best >= BOOT_ANIM_FAT_TRAIL ? BOOT_ANIM_FAT_WIDTH : 1;

    return s;
}

/*---------------------------------------------------------------------------
 * The finale
 *
 * The camera does not stop turning once the curve is finished, and the
 * origin does not stop drifting either: while the title arrives, both keep
 * moving, further than the curve-drawing phase alone ever took them, ending
 * where the t axis reads vertical again - much as it did at the very start,
 * but now seen from past the point the floor went edge-on to a line - while
 * the origin has slid left, leaving room for the word beside it.
 *
 * Three effects - the extra turn, the origin's horizontal slide, and the
 * axes losing their labelled tips to become unbounded lines like the floor
 * already is - share ONE clock rather than three independent ones, the same
 * reasoning as the first half of the orbit: driven by a single progress
 * value, they cannot drift out of sync with each other or with how far the
 * title has arrived, because it is the SAME window - start to finish - that
 * paces the letters.
 *
 * Placed here, after "Colour", rather than beside "The camera" it extends:
 * boot_anim_view() needs boot_anim_pen(), which is defined above in this
 * same section, and boot_anim_finale_reach() below needs the title's own
 * timing constants - so this is the first point in the file everything it
 * touches already exists.
 *-------------------------------------------------------------------------*/

/* When the last letter lands - the finale's own finish line. */
#define BOOT_ANIM_FINALE_END_MS (BOOT_ANIM_TITLE_START_MS +               \
    (BOOT_ANIM_TITLE_LEN - 1) * BOOT_ANIM_TITLE_STAGGER_MS +              \
    BOOT_ANIM_TITLE_FLIGHT_MS)

static inline uint8_t boot_anim_finale_reach(uint32_t now_ms)
{
    return boot_anim_ease_out(boot_anim_ramp(
        now_ms, BOOT_ANIM_TITLE_START_MS,
        BOOT_ANIM_FINALE_END_MS - BOOT_ANIM_TITLE_START_MS));
}

/* The extra turn: on top of BOOT_ANIM_PHI_END_PHASE (58 degrees, reached
 * when the curve finishes), the finale adds another 82 - a total of 140 -
 * which is where the t axis's own screen weight, having passed through zero
 * around 52 degrees (fully foreshortened - "pointing at the screen"), has
 * grown back to roughly its starting magnitude. See boot_anim_view()'s own
 * comment for the reasoning that led here, and the file's own top comment,
 * "THE CAMERA ORBITS", for what it looks like. */
#define BOOT_ANIM_PHI_EXTRA_PHASE 14928   /* round(82 / 360 * 65536) */

/* How far left the origin slides during the finale. The title no longer
 * reads this - it rests at a fixed point in its own viewer's frame now, see
 * "The title" - so this is purely a camera-side number. */
#define BOOT_ANIM_ORIGIN_SHIFT_PX 94

/* How far the two floor-plane axes reach once unbounded, matching the
 * floor's own FLOOR_REACH in boot_anim.c - the same "run it well past the
 * panel and let clipping do the work" reasoning applies to an axis exactly
 * as much as to a grid line. */
#define BOOT_ANIM_AXIS_FAR_UNITS 24

/* The view for `now_ms`. Constructed here rather than in "The camera" above
 * because it depends on both boot_anim_pen() (the curve's own progress) and
 * boot_anim_finale_reach() (just above) - the boot_anim_view_t TYPE had to
 * exist early, for boot_anim_screen_x()/screen_y() to compile against it,
 * but the constructor did not.
 *
 * oy is unaffected by the finale on purpose: it already reached its mirror
 * position - see boot_anim_origin_y()'s own comment - by the time the curve
 * finished, and letting three things drift at once (turn, and two
 * directions of slide) was one degree of freedom more than the picture
 * needed. Only ox moves further. */
static inline boot_anim_view_t boot_anim_view(int w, int h, uint32_t now_ms)
{
    const int32_t curve_progress = boot_anim_pen(now_ms);   /* 0..ONE */
    const uint8_t finale = boot_anim_finale_reach(now_ms);  /* 0..255 */

    const int32_t phase32 =
        ((curve_progress * BOOT_ANIM_PHI_END_PHASE) >> BOOT_ANIM_Q) +
        (((int32_t)finale * BOOT_ANIM_PHI_EXTRA_PHASE) / 255);
    const uint16_t phase = (uint16_t)phase32;
    const int32_t c15 = boot_anim_cos(phase);
    const int32_t s15 = boot_anim_sin(phase);

    boot_anim_view_t v;
    v.re_y = ((BOOT_ANIM_D_RE_Y * c15 + BOOT_ANIM_B_RE_Y * s15) >> 15) +
             BOOT_ANIM_C_RE_Y;
    v.im_y = ((BOOT_ANIM_D_IM_Y * c15 + BOOT_ANIM_B_IM_Y * s15) >> 15) +
             BOOT_ANIM_C_IM_Y;
    v.t_y  = ((BOOT_ANIM_D_T_Y  * c15 + BOOT_ANIM_B_T_Y  * s15) >> 15) +
             BOOT_ANIM_C_T_Y;

    const int oy_start = boot_anim_origin_y(h);
    v.oy = oy_start +
           (int)((((int64_t)(h - 2 * oy_start)) * curve_progress) >>
                 BOOT_ANIM_Q);

    v.ox = boot_anim_origin_x(w) -
           ((int)finale * BOOT_ANIM_ORIGIN_SHIFT_PX) / 255;

    return v;
}

/* The curve's own shrink, toward the view's origin, as the finale turns the
 * camera the rest of the way. Not part of boot_anim_view_t: it applies to
 * the drawn curve alone, never to the axes, which stay unbounded lines
 * reaching for the panel edge exactly as they did before this existed - see
 * boot_anim.c's draw_curve()/draw_heads() for where this is spent (a scale
 * on the pixel offset from view->ox/oy, applied after projection) versus
 * draw_axes(), which never calls this at all.
 *
 * The number: continuing the turn to BOOT_ANIM_PHI_EXTRA_PHASE regrows the
 * t axis's screen weight back toward its starting size (see that constant's
 * own comment), which - with the origin frozen close to the top of the
 * panel, room having only ever been reserved on ONE side of it, for the
 * climb the curve made getting there - would run the tall end of an
 * unshrunk curve off the panel. Shrinking it back down as the turn resumes
 * is what keeps the same curve inside the same room. BOOT_ANIM_SHRINK_MS
 * and BOOT_ANIM_SHRINK_FLOOR_Q8 were both chosen by sweeping the actual
 * projection at a 5ms step across the whole finale and shrinking until
 * nothing overflowed, with headroom to spare - not derived from geometry,
 * because oy is fixed but the panel edge closest to the curve's reach
 * changes with it, which is exactly the kind of thing worth measuring
 * rather than re-deriving by hand. */
#define BOOT_ANIM_SHRINK_MS        900
#define BOOT_ANIM_SHRINK_FLOOR_Q8  51    /* ~0.2, floor is held once reached */

static inline int boot_anim_curve_shrink_q8(uint32_t now_ms)
{
    const uint8_t u8 = boot_anim_ease_out(boot_anim_ramp(
        now_ms, BOOT_ANIM_TITLE_START_MS, BOOT_ANIM_SHRINK_MS));
    return 256 - (((int)u8 * (256 - BOOT_ANIM_SHRINK_FLOOR_Q8)) / 255);
}

/*---------------------------------------------------------------------------
 * The one hardware-facing entry point
 *
 * Declared here and defined in boot_anim.c, the same arrangement icon_check()
 * has at the bottom of icons.h: a declaration costs this header none of its
 * host-portability, and a second header for one function would be worse.
 *-------------------------------------------------------------------------*/

/* Draw the whole animation, start to finish - about BOOT_ANIM_MS of it.
 *
 * BLOCKS, and is meant to: it runs during boot, before the shell's frame loop
 * exists and before there is anything to switch to. gfx_init() must have
 * succeeded first. Yields every frame so the watchdog stays fed. */
void boot_anim_run(void);
